self._getNextSelectableDate = function(date, increment) {
    var next = new Date(date.getTime());
    var step = increment;
    var maxSteps = 366;
    var steps = 0;
    while (steps < maxSteps) {
        next.setTime(next.getTime() + step * 24*60*60*1000);
        steps++;
        var isDisabled = false;
        if (opts.minDate && next < opts.minDate) isDisabled = true;
        if (opts.maxDate && next > opts.maxDate) isDisabled = true;
        if (opts.disableWeekends && isWeekend(next)) isDisabled = true;
        if (opts.disableDayFn && opts.disableDayFn(next)) isDisabled = true;
        if (!isDisabled) {
            return next;
        }
    }
    return date;
};

self._onKeyChange = function(e)
{

edits.before:
switch(e.keyCode){
    case 13:
    case 27:
        if (opts.field) {
            opts.field.blur();
        }
        break;
    case 37:
        self.adjustDate('subtract', 1);
        break;
    case 38:
        self.adjustDate('subtract', 7);
        break;
    case 39:
        self.adjustDate('add', 1);
        break;
    case 40:
        self.adjustDate('add', 7);
        break;
    case 8:
    case 46:
        self.setDate(null);
        break;
}

edits.after:
switch(e.keyCode){
    case 13:
    case 27:
        if (opts.field) {
            opts.field.blur();
        }
        break;
    case 37:
        var newDate = self._getNextSelectableDate(self.getDate() || new Date(), -1);
        self.setDate(newDate);
        break;
    case 38:
        var newDate = self._getNextSelectableDate(self.getDate() || new Date(), -7);
        self.setDate(newDate);
        break;
    case 39:
        var newDate = self._getNextSelectableDate(self.getDate() || new Date(), 1);
        self.setDate(newDate);
        break;
    case 40:
        var newDate = self._getNextSelectableDate(self.getDate() || new Date(), 7);
        self.setDate(newDate);
        break;
    case 8:
    case 46:
        self.setDate(null);
        break;
}
